import {
	ConfigValueRecord,
	ConfigValueRecordTyped,
	ParameterSpecRecord,
	RuleConfigType,
} from "#base/scripts/voronoi-types.js";

import { PlateRegion, VoronoiRegion } from "../voronoi-region.js";
import { RegionCell, WrapDistOptions } from "../voronoi-utils.js";

export interface ScoringContext {
	cells: RegionCell[];
	region: VoronoiRegion;
	regions: VoronoiRegion[];
	plateRegions: PlateRegion[];
	m_worldDims: float2;
	totalArea: number;
	cellCount: number;
	rules: Record<string, Rule>;
	wrap: WrapDistOptions;
}

export abstract class Rule {
	abstract name: string;
	description?: string;
	isActive = false;
	weight = 1.0;

	abstract parameterSpecs: ParameterSpecRecord;
	abstract configValues: ConfigValueRecord;

	abstract score(cell: RegionCell, ctx: ScoringContext): number;
	public notifySelectedCell(_cell: RegionCell, _ctx: ScoringContext): void {}

	initialize(config: RuleConfigType) {
		this.isActive = config.isActive;
		this.weight = config.weight;
		if (config.config) {
			for (const [recordName, recordValue] of Object.entries(config.config)) {
				if (recordName in this.configValues) {
					this.configValues[recordName] = recordValue;
				}
			}
		}
		/*
		if (config.internalConfig) {
			for (const [recordName, recordValue] of Object.entries(config.internalConfig)) {
				if (recordName in this) {
					this[recordName as keyof this] = recordValue;
				} else {
					console.log("Unable to find " + recordName + " in " + this.name);
				}
			}
		}
		*/
	}

	static createDefaultsFromSpecs<TSpecs extends ParameterSpecRecord>(specs: TSpecs): ConfigValueRecordTyped<TSpecs> {
		const result: any = {};
		for (const key in specs) {
			if (!Object.prototype.hasOwnProperty.call(specs, key)) continue;
			const node = specs[key];
			if ("children" in node) {
				result[key] = [];
			} else {
				result[key] = node.default;
			}
		}
		return result;
	}

	prepare() {} // Optionally overridden

	scoreAllCells(
		filter: (value: RegionCell) => boolean,
		ctx: ScoringContext,
		regionIdGetter: (value: RegionCell) => VoronoiRegion,
		weight: number = this.weight,
	) {
		this.prepare();
		for (const cell of ctx.cells) {
			if (filter(cell)) {
				ctx.region = regionIdGetter(cell);
				cell.currentScore += this.score(cell, ctx) * weight;
			}
		}
	}

	scoreCells(
		cells: RegionCell[],
		ctx: ScoringContext,
		regionIdGetter: (value: RegionCell) => VoronoiRegion,
		weight: number = this.weight,
	) {
		this.prepare();
		for (const cell of cells) {
			ctx.region = regionIdGetter(cell);
			cell.currentScore += this.score(cell, ctx) * weight;
		}
	}
}
